/**
 * Model users
 * One login system for Super Admins, Hotel Owners, Branch Managers, and Staff.
 * Scope is determined by branch_id + role, not by which table the row lives in.
 * Hotel-owner-specific data (hotel_id, address) lives in hotel_owners, a 1-to-1
 * profile table — NOT a separate login system.
 */
export type users = $Result.DefaultSelection<Prisma.$usersPayload>
/**
 * Model roles
 * 
 */
export type roles = $Result.DefaultSelection<Prisma.$rolesPayload>
/**
 * Model permissions
 * 
 */
export type permissions = $Result.DefaultSelection<Prisma.$permissionsPayload>
/**
 * Model role_permissions
 * 
 */
export type role_permissions = $Result.DefaultSelection<Prisma.$role_permissionsPayload>
/**
 * Model buyers
 * Online customers who order/book from the public web app.
 * Entirely separate from `customers` (which are POS walk-ins added
 * by staff, scoped per-hotel). A buyer logs in with email or phone
 * and can order at ANY hotel on the platform.
 */
export type buyers = $Result.DefaultSelection<Prisma.$buyersPayload>
/**
 * Model hotels
 * This table contains check constraints and requires additional setup for migrations.
 */
export type hotels = $Result.DefaultSelection<Prisma.$hotelsPayload>
/**
 * Model hotel_owners
 * Hotel Owner profile — 1-to-1 with users, 1-to-1 with hotels.
 * user_id IS the primary key: this is a profile, not a separate login.
 * One user owns exactly one hotel; one hotel has exactly one owner.
 */
export type hotel_owners = $Result.DefaultSelection<Prisma.$hotel_ownersPayload>
/**
 * Model pending_signups
 * 
 */
export type pending_signups = $Result.DefaultSelection<Prisma.$pending_signupsPayload>
/**
 * Model email_verifications
 * 
 */
export type email_verifications = $Result.DefaultSelection<Prisma.$email_verificationsPayload>
/**
 * Model subscription_plans
 * 
 */
export type subscription_plans = $Result.DefaultSelection<Prisma.$subscription_plansPayload>
/**
 * Model sections
 * Master catalogue of every gated feature area ("section") in the app.
 * e.g. key = "rooms", "pos", "inventory", "kitchen", "payroll", "reports" ...
 */
export type sections = $Result.DefaultSelection<Prisma.$sectionsPayload>
/**
 * Model plan_sections
 * Which sections each plan unlocks. Join table.
 */
export type plan_sections = $Result.DefaultSelection<Prisma.$plan_sectionsPayload>
/**
 * Model provinces
 * 
 */
export type provinces = $Result.DefaultSelection<Prisma.$provincesPayload>
/**
 * Model branches
 * This table contains check constraints and requires additional setup for migrations.
 */
export type branches = $Result.DefaultSelection<Prisma.$branchesPayload>
/**
 * Model audit_logs
 * actor_id intentionally has no FK — audit rows must survive user deletion.
 */
export type audit_logs = $Result.DefaultSelection<Prisma.$audit_logsPayload>
/**
 * Model customers
 * Local walk-in customer added by staff at POS. Per-hotel. No login.
 * Online buyers are stored in `buyers` — they are separate identities.
 */
export type customers = $Result.DefaultSelection<Prisma.$customersPayload>
/**
 * Model dining_areas
 * 
 */
export type dining_areas = $Result.DefaultSelection<Prisma.$dining_areasPayload>
/**
 * Model dining_tables
 * 
 */
export type dining_tables = $Result.DefaultSelection<Prisma.$dining_tablesPayload>
/**
 * Model table_sessions
 * 
 */
export type table_sessions = $Result.DefaultSelection<Prisma.$table_sessionsPayload>
/**
 * Model menu_categories
 * 
 */
export type menu_categories = $Result.DefaultSelection<Prisma.$menu_categoriesPayload>
/**
 * Model menu_items
 * 
 */
export type menu_items = $Result.DefaultSelection<Prisma.$menu_itemsPayload>
/**
 * Model menu_item_modifier_groups
 * 
 */
export type menu_item_modifier_groups = $Result.DefaultSelection<Prisma.$menu_item_modifier_groupsPayload>
/**
 * Model menu_item_modifiers
 * 
 */
export type menu_item_modifiers = $Result.DefaultSelection<Prisma.$menu_item_modifiersPayload>
/**
 * Model inventory_items
 * 
 */
export type inventory_items = $Result.DefaultSelection<Prisma.$inventory_itemsPayload>
/**
 * Model menu_item_ingredients
 * 
 */
export type menu_item_ingredients = $Result.DefaultSelection<Prisma.$menu_item_ingredientsPayload>
/**
 * Model inventory_transactions
 * 
 */
export type inventory_transactions = $Result.DefaultSelection<Prisma.$inventory_transactionsPayload>
/**
 * Model orders
 * An order is EITHER a POS order (customer_id set, buyer_id null)
 * OR an online order (buyer_id set, customer_id null). Never both.
 */
export type orders = $Result.DefaultSelection<Prisma.$ordersPayload>
/**
 * Model online_order_details
 * 
 */
export type online_order_details = $Result.DefaultSelection<Prisma.$online_order_detailsPayload>
/**
 * Model platform_settings
 * 
 */
export type platform_settings = $Result.DefaultSelection<Prisma.$platform_settingsPayload>
/**
 * Model order_payouts
 * 
 */
export type order_payouts = $Result.DefaultSelection<Prisma.$order_payoutsPayload>
/**
 * Model order_items
 * 
 */
export type order_items = $Result.DefaultSelection<Prisma.$order_itemsPayload>
/**
 * Model kitchen_ticket_items
 * 
 */
export type kitchen_ticket_items = $Result.DefaultSelection<Prisma.$kitchen_ticket_itemsPayload>
/**
 * Model kitchen_tickets
 * 
 */
export type kitchen_tickets = $Result.DefaultSelection<Prisma.$kitchen_ticketsPayload>
/**
 * Model reviews
 * A review is always written by a logged-in buyer (self-signup,
 * platform-wide). POS walk-in customers CANNOT review — no
 * `customer_id` field on purpose. `order_id` links the review
 * back to the specific order the buyer placed.
 */
export type reviews = $Result.DefaultSelection<Prisma.$reviewsPayload>
/**
 * Model discounts
 * 
 */
export type discounts = $Result.DefaultSelection<Prisma.$discountsPayload>
/**
 * Model order_discounts
 * 
 */
export type order_discounts = $Result.DefaultSelection<Prisma.$order_discountsPayload>
/**
 * Model payment_methods
 * 
 */
export type payment_methods = $Result.DefaultSelection<Prisma.$payment_methodsPayload>
/**
 * Model payments
 * 
 */
export type payments = $Result.DefaultSelection<Prisma.$paymentsPayload>
/**
 * Model invoices
 * 
 */
export type invoices = $Result.DefaultSelection<Prisma.$invoicesPayload>
/**
 * Model pos_devices
 * 
 */
export type pos_devices = $Result.DefaultSelection<Prisma.$pos_devicesPayload>
/**
 * Model printers
 * 
 */
export type printers = $Result.DefaultSelection<Prisma.$printersPayload>
/**
 * Model shifts
 * 
 */
export type shifts = $Result.DefaultSelection<Prisma.$shiftsPayload>
/**
 * Model staff_leave_requests
 * 
 */
export type staff_leave_requests = $Result.DefaultSelection<Prisma.$staff_leave_requestsPayload>
/**
 * Model expense_categories
 * Category bucket for expenses (Rent, Utilities, Maintenance, Supplies...)
 * Scoped at hotel level so all branches of a hotel share the same categories.
 */
export type expense_categories = $Result.DefaultSelection<Prisma.$expense_categoriesPayload>
/**
 * Model expenses
 * Day-to-day operating expenses for a branch (rent, utilities, repairs,
 * supplier purchases that aren't inventory, etc). Distinct from
 * staff payroll, which lives in payslips below.
 */
export type expenses = $Result.DefaultSelection<Prisma.$expensesPayload>
/**
 * Model staff_salaries
 * Current + historical salary structure per staff member.
 * Keep old rows (is_current = false) instead of overwriting, so payroll
 * history stays accurate even after a raise.
 */
export type staff_salaries = $Result.DefaultSelection<Prisma.$staff_salariesPayload>
/**
 * Model payroll_runs
 * One payroll batch per branch per pay period (e.g. "August 2026").
 */
export type payroll_runs = $Result.DefaultSelection<Prisma.$payroll_runsPayload>
/**
 * Model payslips
 * One line per staff member within a payroll run — the actual amount paid.
 */
export type payslips = $Result.DefaultSelection<Prisma.$payslipsPayload>
/**
 * Model staff_advances
 * Salary advances / loans given to staff, later deducted from a payslip.
 */
export type staff_advances = $Result.DefaultSelection<Prisma.$staff_advancesPayload>
/**
 * Model tutorials
 * 
 */
export type tutorials = $Result.DefaultSelection<Prisma.$tutorialsPayload>
/**
 * Model staff_attendance
 * Clock-in/out records used to compute payroll deductions.
 */
export type staff_attendance = $Result.DefaultSelection<Prisma.$staff_attendancePayload>
/**
 * Model room_types
 * Physical room types configured per branch (Double, VIP, Single...).
 */
export type room_types = $Result.DefaultSelection<Prisma.$room_typesPayload>
/**
 * Model rooms
 * One row per physical room in a branch.
 * status: available | occupied | cleaning | maintenance
 */
export type rooms = $Result.DefaultSelection<Prisma.$roomsPayload>
/**
 * Model room_stays
 * A running stay for one room. Can be assigned to a POS customer
 * (staff-checked-in walk-in) OR to an online buyer (self-booked).
 * Exactly one of customer_id / buyer_id is set.
 */
export type room_stays = $Result.DefaultSelection<Prisma.$room_staysPayload>

